static bool Empty(const NativeKeyFramer::Builder& k){return !k.records&&!k.bindings&&!k.details&&!k.count&&!k.totalKeys&&!k.totalBytes;}
static bool Rejected(NativeKeyFramer::Builder& keys,const NativePreparedRenderScene::Context& scene,const NativeKeyFramer::Settings& settings,unsigned int node=0xffffffffu){return !keys.Build(scene,settings)&&Empty(keys)&&keys.error==keys.diagnostic&&keys.error&&keys.error[0]&&keys.errorNode==node;}
static bool ObjectsEmpty(const NativeObjectsCompiler::Builder& b){return !b.data&&!b.size&&!b.count&&!b.properties;}
static bool ObjectRejected(NativeObjectsCompiler::Builder& b,const NativePreparedRenderScene::Context& scene,const NativeObjectsCompiler::Settings& settings,unsigned int node,const char* property=0){return !b.Build(scene,settings)&&ObjectsEmpty(b)&&b.error==b.diagnostic&&b.error&&b.error[0]&&b.errorNode==node&&(!property||GameClassMetadata::Exact(b.errorProperty,property));}
static bool JointEmpty(const NativeKeyFramerObjects::Builder& b){return !b.objects&&!b.blind&&!b.objectsBytes&&!b.blindBytes&&!b.objectCount&&!b.keyFramerCount&&!b.keyCount;}
// Independent read of disk Objects framing: return the actual prior pool name,
// not an API metadata pointer or a synthesized offset into output storage.
